package gates

import (
	"path/filepath"
	"testing"

	"github.com/DonaldMurillo/gofastr/cmd/gofastr/internal/clitest"
)

const goroutineUI = "package app\n\nfunc view() { go func() {}() }\n"

func TestSandboxReadsOnlyUiGoFiles(t *testing.T) {
	root := clitest.WriteA11yTree(t, map[string]string{
		"app/worker.go":  goroutineUI,
		"app/view.ui.go": goroutineUI,
		"gen/out.ui.go":  "// Code generated by gofastr. DO NOT EDIT.\n" + goroutineUI,
	})
	findings, err := auditSandbox(root)
	if err != nil {
		t.Fatal(err)
	}
	if len(findings) == 0 {
		t.Fatal("the sandbox lint passed a .ui.go file that starts a goroutine")
	}
	for _, f := range findings {
		if f.File != filepath.Join("app", "view.ui.go") {
			t.Errorf("the sandbox lint read %s; it reads only hand-written .ui.go files", f.File)
		}
	}
}

func TestAuditSkipsUnparsableFilesAndSortsFindings(t *testing.T) {
	root := clitest.WriteA11yTree(t, map[string]string{
		"b/screen.go":  clitest.BadScreen,
		"a.go":         clitest.BadScreen,
		"a/screen.go":  clitest.BadScreen + "\nfunc other() any { return html.Image(html.ImageConfig{Src: \"/y.png\"}) }\n",
		"a/broken.go":  "package app\n\nfunc {\n",
		"c/broken.go":  "package app\n\nfunc {\n",
		"c/screen.go":  "package app\n",
		"c/view.ui.go": "package app\n\nfunc {\n",
	})
	findings, err := AuditA11y(root)
	if err != nil {
		t.Fatalf("a file that does not parse stopped the audit: %v", err)
	}
	if _, err := auditSandbox(root); err != nil {
		t.Fatalf("a .ui.go file that does not parse stopped the sandbox audit: %v", err)
	}
	var got []string
	for _, f := range findings {
		got = append(got, filepath.ToSlash(f.File))
	}
	if len(findings) != 4 || got[0] != "a.go" || got[1] != "a/screen.go" || got[2] != "a/screen.go" || got[3] != "b/screen.go" || findings[1].Line >= findings[2].Line {
		t.Fatalf("findings are not in file and line order: %+v", findings)
	}
}
